ap=[p('Arista '+n,d,A,roles=['developer'],typ='product',sector='energy_storage',sub='batteries',attributes={'evidence_period':'2012 annual report','current_availability':'unverified'},aliases=als) for n,d,als in [('Power on Demand','Battery-based peak-demand management system.',[]),('Mobile Renewable Power Station','Mobile hybrid energy system incorporating battery storage.',['Arista MRPS']),('Renewable Power Station','Stationary hybrid power system with storage integration.',['Arista RPS'])]]
